import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"Claude Code","description":"","frontmatter":{},"headers":[],"relativePath":"guide/claude-code.md","filePath":"guide/claude-code.md","lastUpdated":1793550481000}'),n={name:"guide/claude-code.md"};function i(l,e,d,r,h,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>By the end of this page Claude Code has the MCP Lens plugin installed, so every MCP tool call in your sessions is recorded locally and the <code>calls</code> column in <code>mcp-lens report</code> stops sitting at zero. You also get the <code>/lens-audit</code> slash command, which pulls a fresh report straight into the conversation.</p><h2 id="the-easy-way-let-the-extension-do-it" tabindex="-1">The easy way: let the extension do it <a class="header-anchor" href="#the-easy-way-let-the-extension-do-it" aria-label="Permalink to &quot;The easy way: let the extension do it&quot;">​</a></h2><p>If you use the VS Code extension, run its <code>MCP Lens: Install Hooks for All Clients</code> command and it installs this plugin for you. See <a href="/MCPLens/guide/vscode-extension">VS Code Extension</a>. If you took that route, skip the manual install section below and continue at <a href="#after-installing">After installing</a>, which applies however the plugin got there.</p><h2 id="install-the-plugin-manually" tabindex="-1">Install the plugin manually <a class="header-anchor" href="#install-the-plugin-manually" aria-label="Permalink to &quot;Install the plugin manually&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/MCPLens/packages/lens-audit-plugin</span></span></code></pre></div><p>Substitute <code>/path/to/MCPLens</code> with the path to your own clone of the repository. This registers the plugin&#39;s hooks and adds the <code>/lens-audit</code> slash command. For local testing without registering a marketplace entry, you can load it with <code>--plugin-dir</code> instead.</p><h2 id="what-it-collects" tabindex="-1">What it collects <a class="header-anchor" href="#what-it-collects" aria-label="Permalink to &quot;What it collects&quot;">​</a></h2><p>The plugin uses only its bundled hook runner; it downloads no runtime and opens neither the network nor the MCP Lens database. For every MCP call it records the minimum: client, session, server, tool name and timestamp, written atomically into <code>~/.mcplens/inbox</code>. It never stores tool inputs, tool responses, prompts or response bodies, and it never touches Claude&#39;s original transcripts or logs.</p><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Reload the Claude Code plugin and start a new session for the hook definitions to take effect. From that new session, run <code>/lens-audit</code> to bring a fresh cost x usage report into context; behind the scenes it runs <code>npx --no-install mcp-lens report --days 30 --format ai</code>, so a separately installed <code>mcp-lens</code> CLI is required for the slash command to work (see <a href="/MCPLens/reference/cli">the CLI reference</a>).</p><p>To stop collection, disable or uninstall the plugin and start a new session.</p>',12)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
